#!/usr/bin/env python3
"""Generate typed wire codecs for this fork; schemas transcribed from its AS3 packet classes."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
types = {'i':'std::int32_t','u':'std::uint32_t','h':'std::int16_t','H':'std::uint16_t','b':'std::uint8_t','f':'float','B':'bool','s':'std::string','p':'Position','v':'std::vector<bool>','V':'std::vector<std::int32_t>','e':'std::vector<std::uint8_t>','t':'std::vector<TradeItem>','d':'std::vector<std::int16_t>','o':'Slot'}
read = {'i':'r.i32()','u':'r.u32()','h':'r.i16()','H':'r.u16()','b':'r.u8()','f':'r.f32()','B':'r.boolean()','s':'r.utf()','p':'position(r)','v':'bools(r)','V':'ints(r)','e':'effects(r)','t':'items(r)','d':'damages(r)'}
write = {'i':'w.i32(V);','u':'w.u32(V);','h':'w.u16(static_cast<std::uint16_t>(V));','H':'w.u16(V);','b':'w.u8(V);','f':'w.f32(V);','B':'w.boolean(V);','s':'w.utf(V);','p':'position(w, V);','v':'bools(w, V);','o':'slot(w, V);'}
incoming = [
('AccountList','ACCOUNTLIST','i list_id,V account_ids'),('AllyShoot','ALLYSHOOT','i owner_id,h container_type,f angle'),
('Aoe','AOE','p position,f radius,H damage,b effect,u color'),('BuyResult','BUYRESULT','i result,s text'),
('CreateSuccess','CREATE_SUCCESS','i object_id,i character_id'),('Damage','DAMAGE','i target_id,e effects,H damage'),
('Death','DEATH','i account_id,i character_id,s killed_by'),('EnemyShoot','ENEMYSHOOT','i bullet_id,i owner_id,b bullet_type,p position,f angle,h damage,b num_shots,f angle_increment'),
('Failure','FAILURE','i error_id,s text'),('GlobalNotification','GLOBAL_NOTIFICATION','i type,s text'),
('Goto','GOTO','i object_id,p position'),('GuildResult','GUILDRESULT','B success,s text'),('InvResult','INVRESULT','i result'),
('InvitedToGuild','INVITEDTOGUILD','s name,s guild_name'),('NameResult','NAMERESULT','B success,s text'),
('Notification','NOTIFICATION','i object_id,s text,u color'),('Ping','PING','i serial'),('PlaySound','PLAYSOUND','s sound'),
('QuestObject','QUESTOBJID','i object_id'),('Reconnect','RECONNECT','i game_id'),
('ServerPlayerShoot','SERVERPLAYERSHOOT','i bullet_id,i owner_id,h container_type,p position,f angle,f angle_increment,d damages'),
('ShowEffect','SHOWEFFECT','b type,i target_id,u color,p position,p position2,B has_position2'),
('Text','TEXT','s name,i object_id,i stars,b bubble_time,s recipient,s text'),
('TradeAccepted','TRADEACCEPTED','v my_offer,v their_offer'),('TradeChanged','TRADECHANGED','v offer'),
('TradeDone','TRADEDONE','i code,s text'),('TradeRequested','TRADEREQUESTED','s name'),('TradeStart','TRADESTART','t my_items,s their_name,t their_items')]
outgoing = [
('AcceptTrade','ACCEPTTRADE','v my_offer,v their_offer'),('AoeAck','AOEACK','i time_ms,p position'),('Buy','BUY','i object_id'),
('CancelTrade','CANCELTRADE',''),('ChangeGuildRank','CHANGEGUILDRANK','s name,i rank'),('ChangeTrade','CHANGETRADE','v offer'),
('ChooseName','CHOOSENAME','s name'),('Create','CREATE','H class_type,H skin_type'),('CreateGuild','CREATEGUILD','s name'),
('EditAccountList','EDITACCOUNTLIST','i list_id,B add,i object_id'),('EnemyHit','ENEMYHIT','i time_ms,i bullet_id,i target_id'),
('Escape','ESCAPE',''),('GotoAck','GOTOACK','i time_ms'),('GuildInvite','GUILDINVITE','s name'),('GuildRemove','GUILDREMOVE','s name'),
('Hello','HELLO','s build_version,i game_id,s username,s password,s map_json'),('InvDrop','INVDROP','b slot_id'),
('InvSwap','INVSWAP','i time_ms,p position,o first,o second'),('JoinGuild','JOINGUILD','s name'),('Load','LOAD','i character_id'),
('Move','MOVE','i time_ms,p position'),('PlayerHit','PLAYERHIT','i bullet_id'),
('PlayerShoot','PLAYERSHOOT','i time_ms,p position,f angle,B ability,b num_shots'),('PlayerText','PLAYERTEXT','s text'),
('Pong','PONG','i serial,i time_ms'),('RequestTrade','REQUESTTRADE','s name'),('Reskin','RESKIN','i skin_id'),
('ShootAck','SHOOTACK','i time_ms'),('SquareHit','SQUAREHIT','i time_ms,i bullet_id'),('Teleport','TELEPORT','i object_id'),
('UseItem','USEITEM','i time_ms,o slot,p position'),('UsePortal','USEPORTAL','i object_id')]
def fields(s): return [x.strip().split() for x in s.split(',') if x.strip()]
header = ['// Generated by tools/generate_messages.py. Schema follows the current Flash fork.','#pragma once','#include "realm/protocol.hpp"','namespace realm::net {','struct Slot { std::int32_t object_id{}; std::uint8_t slot_id{}; };','struct TradeItem { std::int32_t item{}, slot_type{}; bool tradeable{}, included{}; };','namespace incoming {']
for name, _, fs in incoming:
    header.append('struct '+name+' { '+ ' '.join(types[k]+' '+f+'{};' for k,f in fields(fs))+' };')
header += ['}', 'using Incoming = std::variant<Update, Tick, MapInfo, ' + ', '.join('incoming::'+x[0] for x in incoming)+'>;', 'struct Event { flash::PacketId id; Incoming data; };','[[nodiscard]] Event decode(const Packet& packet);','namespace outgoing {']
for name, _, fs in outgoing:
    header.append('struct '+name+' { '+ ' '.join(types[k]+' '+f+ ('{1};' if name=='PlayerShoot' and f=='num_shots' else '{};') for k,f in fields(fs))+' };')
    header.append('[[nodiscard]] Packet encode(const '+name+'& message);')
header += ['}', '}']
source = ['// Generated by tools/generate_messages.py.','#include "realm/messages.hpp"','#include <limits>','namespace realm::net {','namespace {',
'Position position(Reader& r) { return {r.f32(),r.f32()}; }',
'void position(Writer& w, Position p) { w.f32(p.x); w.f32(p.y); }',
'void slot(Writer& w, Slot s) { w.i32(s.object_id); w.u8(s.slot_id); }',
'std::size_t count(Reader& r) { const auto n = r.i16(); if (n < 0) throw ProtocolError("Negative array count"); return static_cast<std::size_t>(n); }',
'std::vector<bool> bools(Reader& r) { std::vector<bool> result(count(r)); for (std::size_t i = 0; i < result.size(); ++i) result[i] = r.boolean(); return result; }',
'std::vector<std::int32_t> ints(Reader& r) { std::vector<std::int32_t> result(count(r)); for (auto& v : result) v = r.i32(); return result; }',
'std::vector<std::uint8_t> effects(Reader& r) { std::vector<std::uint8_t> result(r.u8()); for (auto& v : result) v = r.u8(); return result; }',
'std::vector<std::int16_t> damages(Reader& r) { std::vector<std::int16_t> result(r.u8()); for (auto& v : result) v = r.i16(); return result; }',
'std::vector<TradeItem> items(Reader& r) { std::vector<TradeItem> result(count(r)); for (auto& v : result) v = {r.i32(),r.i32(),r.boolean(),r.boolean()}; return result; }',
'void bools(Writer& w, const std::vector<bool>& values) { if (values.size() > 32767) throw ProtocolError("Offer array too long"); w.u16(static_cast<std::uint16_t>(values.size())); for (const auto v : values) w.boolean(v); }',
'}', 'Event decode(const Packet& packet) { const auto id = static_cast<flash::PacketId>(packet.id); Reader r(packet.body); switch(id) {',
'case flash::PacketId::UPDATE: return {id, parse_update(packet.body)};', 'case flash::PacketId::NEWTICK: return {id, parse_tick(packet.body)};', 'case flash::PacketId::MAPINFO: return {id, parse_map_info(packet.body)};']
for name, enum, fs in incoming:
    source.append('case flash::PacketId::'+enum+': { incoming::'+name+' m;')
    for k,f in fields(fs):
        if name=='EnemyShoot' and f=='num_shots': source.append('if (r.remaining()) { m.num_shots = r.u8(); m.angle_increment = r.f32(); } else m.num_shots = 1;');break
        if name=='ShowEffect' and f=='position2': source.append('if (r.remaining()) { m.position2 = position(r); m.has_position2 = true; }');break
        source.append('m.'+f+' = '+read[k]+';')
    source.append('r.finish(); return {id, std::move(m)}; }')
source += ['default: throw ProtocolError("Unknown or outgoing packet ID");','} }','namespace outgoing {']
for name, enum, fs in outgoing:
    source.append('Packet encode(const '+name+'&'+(' m' if fs else '')+') { Writer w;')
    for k,f in fields(fs):
        if name=='Hello' and f=='map_json': source.append('if (m.map_json.size() > max_packet_length - 5) throw ProtocolError("Map JSON too large");\n w.u32(static_cast<std::uint32_t>(m.map_json.size())); w.raw(std::span(reinterpret_cast<const std::uint8_t*>(m.map_json.data()),m.map_json.size()));');continue
        if name=='PlayerShoot' and f=='num_shots': source.append('if (m.num_shots != 1) w.u8(m.num_shots);');continue
        source.append(write[k].replace('V','m.'+f))
    source.append('return {static_cast<std::uint8_t>(flash::PacketId::'+enum+'), w.bytes()}; }')
source += ['}', '}']
(root/'include/realm/messages.hpp').write_text('\n'.join(header)+'\n')
(root/'src/messages.cpp').write_text('\n'.join(source)+'\n')
